import {labels,score,rank,filterCases,reviewMessage} from './logic.js';
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;
try{const r=await fetch('./catalogue.json');if(!r.ok)throw Error('The catalogue could not be loaded.');data=await r.json();}catch(e){$('#library').innerHTML='<div class="loading-error">The opportunity catalogue could not be loaded. Please refresh the page.</div>';throw e;}
let weights={...data.weights},scope='Healthcare',page='library';const compared=new Set();
const byId=new Map(data.cases.map(c=>[c.id,c])),examples=new Map(data.examples.map(e=>[e.id,e]));
const companyNames=c=>[...new Set((c.examples||[]).map(id=>examples.get(id).organization))];
const briefTitles={};
function goPage(target){page=target;$$('.page').forEach(e=>e.classList.toggle('active',e.id===target));$$('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===target||(target==='library'&&e.hasAttribute('data-scope')&&e.dataset.scope===scope)));$('#breadcrumb').textContent=target==='library'?(scope||'All opportunities'):({dashboard:'Overview dashboard',shortlist:'The first five',evidence:'Source map',demo:'Inbox demo'})[target];document.body.classList.remove('menu-open');window.scrollTo({top:0,behavior:'smooth'});}
function setScope(value){scope='Healthcare';$('#search').value='';$('#area').value='';$('#level').value='';$('#source').value='';const areas=[...new Set(data.cases.map(c=>c.sub_category))].sort();$('#area').innerHTML='<option value="">Every area</option>'+areas.map(a=>`<option>${esc(a)}</option>`).join('');$('#libraryTitle').textContent='Explore all healthcare workflows';goPage('library');render();}
function bindOpen(container){container.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDetail(b.dataset.open));}
function renderShortlist(){const top=rank(data,weights).slice(0,5);$('#spotlights').innerHTML=top.map((c,i)=>`<button class="spotlight" data-open="${c.id}"><div class="spotlight-top"><span>0${i+1}</span><span>${score(c,weights)} / 100</span></div><h3>${esc(briefTitles[c.id]||c.title)}</h3><div class="spotlight-bottom"><span>${esc(c.sub_category)}</span><span>↗</span></div></button>`).join('');bindOpen($('#spotlights'));$('#shortlistRows').innerHTML=top.map((c,i)=>`<article class="shortlist-row"><div class="number">0${i+1}</div><div><h2>${esc(c.title)}</h2><p>${esc(c.workflow)}</p><span class="review-level">${esc(c.user)} · ${esc(c.risk)} demo review burden</span><p><button class="text-button" data-open="${c.id}">Open prototype brief ↗</button></p></div><span class="score">${score(c,weights)} <small>/ 100</small></span></article>`).join('');bindOpen($('#shortlistRows'));}
function render(){const cases=filterCases(data,weights,{scope,query:$('#search').value,area:$('#area').value,level:$('#level').value,source:$('#source').value});$('#resultCount').textContent=`${cases.length} opportunities${scope?' in '+scope.toLowerCase():''} · ranked by your priorities`;$('#opportunities').innerHTML=cases.map(c=>{const names=companyNames(c);return `<article class="opportunity"><div class="card-top"><span class="area-tag">${esc(c.category==='Other healthcare'?c.sector:c.sub_category)}</span><span class="score">${score(c,weights)} <small>/ 100</small></span></div><h3><button data-open="${c.id}">${esc(c.title)}</button></h3><p>${esc(c.workflow)}</p><div class="card-companies">${names.length?esc(names.slice(0,2).join(' · '))+(names.length>2?` +${names.length-2} more`:''):'From original research'} <span>· ${c.examples.length} mapped entries</span></div><div class="card-bottom"><label><input type="checkbox" data-compare="${c.id}" ${compared.has(c.id)?'checked':''}>Compare</label><span class="review-level">${esc(c.risk)} review</span><button data-open="${c.id}">View brief ↗</button></div></article>`}).join('')||'<div class="empty">No workflows match these filters. Try a broader search or another area.</div>';bindOpen($('#opportunities'));$('#opportunities').querySelectorAll('[data-compare]').forEach(e=>e.onchange=()=>{if(e.checked&&compared.size>=3){e.checked=false;$('#compareCount').textContent='Three selected. Remove one to choose another.';return}e.checked?compared.add(e.dataset.compare):compared.delete(e.dataset.compare);renderComparison()});renderShortlist();renderDashboard();renderComparison();}
function renderComparison(){const cs=[...compared].map(id=>byId.get(id));$('#compareCount').textContent=cs.length?`${cs.length} selected for comparison`:'Select up to 3 to compare';$('#comparison').hidden=!cs.length;$('#comparison').innerHTML=cs.length?`<div class="compare-box"><h3>Compare selected workflows <button id="clearCompare" class="text-button">Clear</button></h3><table><thead><tr><th></th>${cs.map(c=>`<th>${esc(c.title)}</th>`).join('')}</tr></thead><tbody>${[['Score',c=>score(c,weights)+' / 100'],['Demo output',c=>c.demo_output],['Review',c=>c.risk],['Measure',c=>c.metric]].map(([label,value])=>`<tr><td>${label}</td>${cs.map(c=>`<td>${esc(value(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';if(cs.length)$('#clearCompare').onclick=()=>{compared.clear();render()};}
function openDetail(id){const c=byId.get(id),s=data.sources.find(s=>s.id===c.source_id);$('#detailContent').innerHTML=`<span class="eyebrow">${esc(c.category)} / ${esc(c.sub_category)}</span><h2>${esc(c.title)}</h2><p>${esc(c.workflow)}</p><div class="detail-meta"><span class="score">${score(c,weights)} <small>/ 100</small></span><span>${esc(c.user)}</span><span>${esc(c.risk)} demo review burden</span></div><h3>The work today</h3><p>${esc(c.pain)}</p><h3>Demo input</h3><p>${esc(c.demo_input)}</p><h3>Reviewable output</h3><p>${esc(c.demo_output)}</p><h3>What to measure</h3><p>${esc(c.metric)}</p><h3>Original HHS entries</h3><div class="source-list">${c.examples.map(id=>{const e=examples.get(id);return `<a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.name)} ↗</a><small> ${esc(e.organization)} · CSV record ${e.row} · ${esc(e.stage)}</small>`}).join('<br><br>')}</div><h3>Source and adaptation</h3><p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><br>${esc(c.locator)}</p><p>${esc(c.adaptation)}</p><p class="footnote">${esc(s.note)}<br>${esc(c.stage)}. Analyst estimates for a fictional-data prototype. Clinical outputs require qualified review. Some original report links require separate access.</p><button class="primary-button" id="downloadBrief">Download prototype brief</button>`;$('#downloadBrief').onclick=()=>downloadBrief(c);$('#detailDialog').showModal();}
function downloadBrief(c){const s=data.sources.find(s=>s.id===c.source_id),text=`# ${c.title}\n\nGroup: ${c.category} / ${c.sector}\nRole: ${c.user}\n\nProblem: ${c.pain}\n\nWorkflow: ${c.workflow}\n\nInput: ${c.demo_input}\n\nOutput: ${c.demo_output}\n\nMeasure: ${c.metric}\n\nSource: ${s.title}, ${c.locator}\n${s.url}\n\nOriginal HHS entries:\n${c.examples.map(id=>{const e=examples.get(id);return e.name+' — '+e.organization+'; CSV record '+e.row+'; '+e.stage+'; '+e.url}).join('\n')}\n\nScope: ${c.adaptation}\n\nScore: ${score(c,weights)}/100. Analyst estimate. Fictional demo inputs. Human approval before action; clinical output requires qualified review.\n`;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.href=url;a.download=c.id+'-brief.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderEvidence(){const q=$('#evidenceSearch').value.toLowerCase(),source=$('#evidenceSource').value,es=data.examples.filter(e=>(!source||e.source_id===source)&&[e.name,e.organization,e.stage,e.mapping_type,...e.case_ids.map(id=>byId.get(id).title)].join(' ').toLowerCase().includes(q));$('#evidenceCount').textContent=`${es.length} of ${data.examples.length} source entries`;$('#evidenceRows').innerHTML=es.map(e=>`<tr><td><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.name)} ↗</a><small>${esc(e.organization)} · CSV record ${e.row}</small></td><td>${e.case_ids.map(id=>`<button class="workflow-link" data-open="${id}">${esc(byId.get(id).title)}</button>`).join('')}</td><td>${esc(e.stage)}</td></tr>`).join('');bindOpen($('#evidenceRows'));}
function renderWeights(){$('#weightControls').innerHTML=Object.keys(weights).map(k=>`<div class="weight-row"><label for="weight-${k}">${labels[k]}</label><input id="weight-${k}" data-weight="${k}" type="range" min="0" max="50" value="${weights[k]}"><output id="output-${k}">${weights[k]}</output></div>`).join('');$$('[data-weight]').forEach(e=>e.oninput=()=>{const next=Number(e.value);if(Object.entries(weights).every(([k,v])=>k===e.dataset.weight?next===0:v===0)){e.value=weights[e.dataset.weight];return}weights[e.dataset.weight]=next;$('#output-'+e.dataset.weight).textContent=next;render()});}
$$('[data-scope]').forEach(e=>e.onclick=()=>setScope(e.dataset.scope));$$('[data-page]').forEach(e=>e.onclick=()=>goPage(e.dataset.page));$('.brand').onclick=e=>{e.preventDefault();goPage('dashboard')};$('#menuToggle').onclick=()=>document.body.classList.toggle('menu-open');
for(const id of ['search','area','level','source'])$('#'+id)[id==='search'?'oninput':'onchange']=render;
$('#evidenceSearch').oninput=renderEvidence;$('#evidenceSource').onchange=renderEvidence;$('#dashboardPriorities').onclick=$('#priorityButton').onclick=$('#shortlistPriorities').onclick=()=>$('#priorityDialog').showModal();$('#closeDetail').onclick=()=>$('#detailDialog').close();$('#closePriorities').onclick=()=>$('#priorityDialog').close();$('#resetWeights').onclick=()=>{weights={...data.weights};renderWeights();render()};
const samples={booking:'Hello, I would like to reschedule my appointment. Can you help?',invoice:'Please send me a copy of my invoice for last week.',clinical:'I have a new symptom and want advice about my medication.'};$$('[data-sample]').forEach(e=>e.onclick=()=>$('#message').value=samples[e.dataset.sample]);$('#runDemo').onclick=()=>{const r=reviewMessage($('#message').value);if(!r){$('#demoResult').textContent='Enter a fictional message first.';return}$('#demoResult').innerHTML=`<span class="eyebrow">PROPOSED OUTPUT</span><h2>${esc(r.category)}</h2><p><b>Review queue:</b> ${esc(r.queue)}</p><h3>Draft for staff approval</h3><p>${esc(r.draft)}</p><p class="footnote">${esc(r.reference)}<br>Pending review. Nothing has been sent. Keyword routing can miss clinical intent.</p>`;};
$('#healthCount').textContent=data.cases.filter(c=>c.category==='Healthcare').length;$('#sourceCount').textContent=data.examples.length;renderWeights();renderEvidence();setScope('Healthcare');goPage('dashboard');

function renderDashboard(){
const colors=['#087f83','#3862c8','#ea9851','#95a6c0','#7657ad','#cb677b'];
const sectors=[...new Set(data.cases.map(c=>c.sub_category))];
$('#donutCount').textContent=data.cases.length;
const counts=sectors.map(k=>data.cases.filter(c=>c.sub_category===k).length);let angle=0;
$('#portfolioDonut').style.background='conic-gradient('+counts.map((n,i)=>{const start=angle;angle+=n/data.cases.length*360;return `${colors[i]} ${start}deg ${angle}deg`}).join(',')+')';
$('#portfolioDonut').setAttribute('aria-label',sectors.map((k,i)=>`${k}: ${counts[i]} workflows`).join(', '));
$('#sectorLegend').innerHTML=sectors.map((k,i)=>`<div><span class="legend-dot" style="background:${colors[i]}"></span><span>${k}</span><strong>${counts[i]}</strong></div>`).join('');
$('#dashboardStats').innerHTML=[[data.cases.length,'Healthcare workflows','Six practical workflow areas','◈'],[data.examples.length,'Selected source records','From the 446-record HHS inventory','↗'],['5','First prototype priorities','Practical, scoped candidates','✦'],['1','Working inbox demo','Fictional data · staff approval','✓']].map(([n,title,detail,icon],i)=>`<article class="stat-card stat-${i}"><span class="stat-icon">${icon}</span><strong>${n}</strong><h3>${title}</h3><p>${detail}</p></article>`).join('');
const glyphs={records:'▤',redaction:'✓',intake:'▤',guidance:'⌕',translation:'↗'};
$('#priorityBars').innerHTML=rank(data,weights).slice(0,5).map((c,i)=>`<button class="priority-card" data-open="${c.id}"><div class="priority-top"><span class="prototype-icon">${glyphs[c.id]||'↗'}</span><span class="prototype-rank">0${i+1}</span></div><h3>${esc(briefTitles[c.id]||c.title)}</h3><p>${esc(c.workflow)}</p><div class="priority-footer"><span>${score(c,weights)}<small> / 100</small></span><span>Open brief →</span></div></button>`).join('');bindOpen($('#priorityBars'));
$('#reviewBars').innerHTML=['Low','Medium','High'].map((k,i)=>{const n=data.cases.filter(c=>c.risk===k).length;return `<div class="review-bar"><div><b>${k} review burden</b><span>${n} workflows · ${Math.round(n/data.cases.length*100)}%</span></div><div class="bar-track"><i style="width:${n/data.cases.length*100}%;background:${['#087f83','#3862c8','#ea9851'][i]}"></i></div></div>`}).join('');
$('#sourceBreakdown').innerHTML=['Deployed','Pilot','Pre-deployment'].map(label=>`<div><strong>${data.examples.filter(e=>e.stage===label).length}</strong><span>HHS ${label.toLowerCase()}</span></div>`).join('');
}
